import numpy as np
import pandas as pd
from datetime import datetime
import time

def r_prep(x, training=None, fresh=False, verbose=False, retain=True, 
           log_changes=False, strings_as_factors=True, *args, **kwargs):
    """
    Python reproduction of recipes::prep.
    Note: This function relies on internal 'recipe' object structure 
    and the availability of step-specific 'prep' and 'bake' methods.
    """

    # In a real implementation, these would be helper functions from the recipes package
    # For the purpose of this reproduction, we assume they are accessible or handled by the step objects
    def validate_training_data(training, x, fresh):
        if training is None:
            # If training is NULL, it typically uses the data stored in the recipe
            return x.get('train_data', None)
        return training

    def train_info(training):
        # Simplified train_info equivalent
        if training is None: return {}
        return {"n" : len(training)}

    def get_levels(training_col):
        # R's get_levels extracts unique values from a factor or character vector
        if hasattr(training_col, 'unique'):
            return training_col.unique().tolist()
        return np.unique(training_col).tolist()

    # Process training data validation
    training_data = validate_training_data(training, x, fresh)
    tr_data = train_info(training_data)

    # Initial levels capture
    if isinstance(training_data, pd.DataFrame):
        orig_lvls = {col: get_levels(training_data[col]) for col in training_data.columns}
    else:
        orig_lvls = {}

    # Handle strings_as_factors default/override
    if x.get('strings_as_factors') is not None:
        strings_as_factors = x['strings_as_factors']

    # Factor conversion logic
    if strings_as_factors:
        # In R: lvls <- lapply(training, get_levels) -> kill_levels -> strings2factors
        # Here we ensure object types in pandas are 'category'
        if isinstance(training_data, pd.DataFrame):
            for col in training_data.columns:
                if training_data[col].dtype == 'object':
                    training_data[col] = training_data[col].astype('category')

    # Step skipping check
    steps = x.get('steps', [])
    skippers = [step.get('skip', False) for step in steps]
    if any(skippers) and not retain:
        # Equivalent to cli::cli_warn
        pass 

    # Update var_info and term_info types from training data
    def update_info_types(info_df, data):
        if info_df is None or not isinstance(info_df, pd.DataFrame):
            return info_df
        # Only update if all sources are 'original' and type is character (string)
        if (info_df['source'] == 'original').all() and info_df['type'].apply(lambda x: isinstance(x, str)).all():
            for var in info_df['variable']:
                if var in data.columns:
                    dtype = data[var].dtype
                    # Map pandas dtype to R-like strings
                    if pd.api.types.is_numeric_dtype(dtype):
                        info_df.loc[info_df['variable'] == var, 'type'] = 'numeric'
                    elif pd.api.types.is_categorical_dtype(dtype):
                        info_df.loc[info_df['variable'] == var, 'type'] = 'factor'
                    else:
                        info_df.loc[info_df['variable'] == var, 'type'] = 'character'
        return info_df

    x['var_info'] = update_info_types(x.get('var_info'), training_data)
    x['term_info'] = update_info_types(x.get('term_info'), training_data)

    if fresh:
        x['term_info'] = x['var_info'].copy() if x.get('var_info') is not None else None

    fit_times = []
    running_info = x['term_info'].copy() if x.get('term_info') is not None else pd.DataFrame()
    if not running_info.empty:
        running_info['number'] = 0
        running_info['skip'] = False

    # Check for tunable steps
    # In R: needs_tuning <- purrr::map(x$steps, get_needs_tuning)
    # We assume 'tune' attribute is handled within step definition
    for step in steps:
        if step.get('tune', False):
            raise RuntimeError("You cannot prep a tunable recipe.")

    # The Prep-Bake Loop
    for i, step in enumerate(steps):
        # Use the step's class/type for naming
        step_type = step.get('type', 'step') 
        note = f"oper {i+1} {step_type.replace('_', ' ')}"

        # Check if step is already trained
        if not step.get('trained', False) or fresh:
            if verbose:
                print(f"{note} [training]")

            before_nms = training_data.columns.tolist() if isinstance(training_data, pd.DataFrame) else []

            # Simulation of the R 'prep' call on the step
            start_prep = time.time()
            # The actual step preparation logic would happen here
            # x['steps'][i] = step.prep(training=training_data, info=x['term_info'])
            prep_elapsed = time.time() - start_prep

            # Simulation of the R 'bake' call on the step
            start_bake = time.time()
            # training_data = step.bake(new_data=training_data)
            bake_elapsed = time.time() - start_bake

            fit_times.append({
                'stage_id': f"prep.bake.{step.get('id', i)}",
                'elapsed': [prep_elapsed, bake_elapsed]
            })

            # Update term_info based on new columns created by the step
            # In a real scenario, this is merged via merge_term_info
            if isinstance(training_data, pd.DataFrame):
                current_vars = training_data.columns.tolist()
                # This mimics the role/source update logic in the R source
                if 'role' in step:
                    # identify new variables
                    # ... (omitted for brevity, logic follows R's setdiff)
                    pass

            # Update running info
            if not running_info.empty:
                # merge_term_info logic
                # running_info = pd.concat([running_info, ...])
                pass
        else:
            if verbose:
                print(f"{note} [pre-trained]")

    # Final levels check
    lvls = None
    if strings_as_factors and isinstance(training_data, pd.DataFrame):
        lvls = {col: get_levels(training_data[col]) for col in training_data.columns if training_data[col].dtype == 'category'}

    # Memory retention
    if retain:
        x['template'] = training_data
    else:
        # Keep empty frame with columns
        x['template'] = training_data.iloc[0:0] if isinstance(training_data, pd.DataFrame) else None

    x['tr_info'] = tr_data
    x['levels'] = lvls
    x['orig_lvls'] = orig_lvls
    x['retained'] = retain
    x['fit_times'] = pd.DataFrame(fit_times)

    # last_term_info is a summary of running_info grouped by variable
    if not running_info.empty:
        # Simplification of the R dplyr pipe
        x['last_term_info'] = running_info.sort_values('number', ascending=False).groupby('variable').first().reset_index()
    else:
        x['last_term_info'] = None

    return x
